with open('conversations.schema.json') as f:
    schema = json.load(f)
defs = schema['definitions']
def get_discriminator_values(ref):
    name = ref[len('#/definitions/'):]
    defn = defs.get(name, {})
    for prop in defn.get('properties', {}).values():
        if 'enum' in prop: return set(prop['enum'])
    return set()
def check(obj, path=''):
    if isinstance(obj, dict):
        if 'oneOf' in obj:
            seen = set()
            for branch in obj['oneOf']:
                ref = branch.get('$ref', '')
                vals = get_discriminator_values(ref)
                overlap = seen & vals
                if overlap: print(f'{path}: overlapping discriminator values {overlap}')
                seen |= vals
        for k, v in obj.items(): check(v, f'{path}/{k}')
    elif isinstance(obj, list):
        for i, v in enumerate(obj): check(v, f'{path}[{i}]')
check(schema)

